class Solution {
    public int differenceOfSums(int n, int m) {
        int res = 0;
        for (int i = 1; i <= n; i++) {
            res += (i % m != 0) ? i : -i;
        }
        return res;
    }
}

class Solution {
    public int differenceOfSums(int n, int m) {
        int totalSum = n * (n + 1) / 2;
        int k = n / m;
        int divSum = m * k * (k + 1) / 2;
        return totalSum - 2 * divSum;
    }
}
